class Calculator:
    def calculate(self, data):
        return sum(item['value'] for item in data)


class PricingDecorator(Calculator):
    def __init__(self, wrapped, item_type, multiplier):
        self._wrapped = wrapped
        self._item_type = item_type
        self._multiplier = multiplier

    def calculate(self, data):
        matching = [item for item in data if item['type'] == self._item_type]
        total = sum(item['value'] * self._multiplier for item in matching)
        return total + self._wrapped.calculate(data)


def build_calculator():
    base = Calculator()
    base = PricingDecorator(base, 'A', 1.1)
    base = PricingDecorator(base, 'B', 0.9)
    base = PricingDecorator(base, 'C', 1.05)
    return base

from abc import ABC, abstractmethod


class Calculator(ABC):
    @abstractmethod
    def calculate(self, data): ...


class BaseCalculator(Calculator):
    def calculate(self, data):
        return sum(item['value'] for item in data)


class PricingDecorator(Calculator, ABC):
    def __init__(self, wrapped, item_type):
        self._wrapped = wrapped
        self._item_type = item_type

    def _matches(self, item):
        return item['type'] == self._item_type

    @abstractmethod
    def _adjust(self, value): ...

    def calculate(self, data):
        matching = [item for item in data if self._matches(item)]
        total = sum(self._adjust(item['value']) for item in matching)
        return total + self._wrapped.calculate(data)


class TypeAPricing(PricingDecorator):
    def __init__(self, wrapped):
        super().__init__(wrapped, 'A')

    def _adjust(self, value):
        return value * 1.1


class TypeBPricing(PricingDecorator):
    def __init__(self, wrapped):
        super().__init__(wrapped, 'B')

    def _adjust(self, value):
        return value * 0.9


class TypeCPricing(PricingDecorator):
    def __init__(self, wrapped):
        super().__init__(wrapped, 'C')

    def _adjust(self, value):
        return value * 1.05


def calculate(data):
    base = BaseCalculator()
    decorated = TypeCPricing(TypeBPricing(TypeAPricing(base)))
    return decorated.calculate(data)

